CREATE OR REPLACE FUNCTION private.record_listing_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  entity text;
  event text;
  previous_status text;
  current_status text;
begin
  if tg_op = 'UPDATE' and to_jsonb(new) - 'updated_at' = to_jsonb(old) - 'updated_at' then
    return new;
  end if;
  entity := case tg_table_name when 'properties' then 'property' when 'rooms' then 'unit' else 'listing' end;
  event := case tg_op when 'INSERT' then 'created' when 'DELETE' then 'deleted' else 'updated' end;
  if tg_table_name = 'vacancies' then
    if tg_op <> 'INSERT' then previous_status := to_jsonb(old)->>'status'; end if;
    if tg_op <> 'DELETE' then current_status := to_jsonb(new)->>'status'; end if;
    if tg_op = 'UPDATE' and current_status is distinct from previous_status then
      event := 'status_changed';
    end if;
  end if;
  insert into public.listing_activity_log(actor_id,entity_type,entity_id,action,old_status,new_status)
    values ((select auth.uid()),entity,
      case when tg_op = 'DELETE' then old.id else new.id end,
      event,previous_status,current_status);
  return case when tg_op = 'DELETE' then old else new end;
end
$function$

CREATE OR REPLACE FUNCTION public.admin_add_listing_icon(p_label text, p_kind text, p_path_d text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_slot text := 'custom-' || replace(gen_random_uuid()::text,'-','');
begin
  if not private.is_admin((select auth.uid())) then
    raise exception 'Not an MFA-verified administrator' using errcode='42501';
  end if;
  p_label := trim(p_label);
  if p_kind not in ('amenity','utility') or length(p_label) not between 2 and 60 then
    raise exception 'Choose a category and a name of 2–60 characters' using errcode='22023';
  end if;
  if p_path_d is null or length(p_path_d) not between 3 and 1200
     or p_path_d !~ '^[MmLlHhVvCcSsQqTtAaZz0-9 .,+-]+$' then
    raise exception 'Use a supported SVG icon' using errcode='22023';
  end if;
  insert into public.site_icon_slots(slot,label,listing_kind) values(v_slot,p_label,p_kind);
  insert into public.site_icon_overrides(slot,path_d) values(v_slot,p_path_d);
  insert into public.site_icon_revisions(slot,path_d,actor_id)
    values(v_slot,p_path_d,(select auth.uid()));
  return v_slot;
end $function$

CREATE OR REPLACE FUNCTION public.admin_deactivate_vacancy(p_vacancy_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private'
AS $function$
begin
  if not private.is_admin((select auth.uid())) then raise exception 'admin required'; end if;
  update public.vacancies set status='removed',updated_at=now() where id=p_vacancy_id;
  if not found then raise exception 'vacancy not found'; end if;
end;$function$

CREATE OR REPLACE FUNCTION public.admin_resolve_report(p_report_id uuid, p_status text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_admin((select auth.uid())) then raise exception 'admin required'; end if;
  if p_status not in ('resolved','dismissed') or length(trim(coalesce(p_reason,'')))<3 then raise exception 'valid status and reason required'; end if;
  update public.reports set status=p_status where id=p_report_id;
  if not found then raise exception 'report not found'; end if;
  insert into public.admin_moderation_log(admin_id,action,target_type,target_id,reason) values ((select auth.uid()),'report_'||p_status,'report',p_report_id,left(trim(p_reason),500));
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_favicon(p_png text, p_revision integer, p_restore boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old public.site_favicon; raw bytea; target text;
begin
 if not private.is_admin(auth.uid()) then raise exception 'Admin verification required' using errcode='42501'; end if;
 select * into old from public.site_favicon where id for update;
 if p_revision is distinct from old.revision then raise exception 'Favicon changed; refresh before saving'; end if;
 target:=case when p_restore then old.previous_png else p_png end;
 if target is not null then
  if length(target)>40000 or target !~ '^data:image/png;base64,[A-Za-z0-9+/=]+$' then raise exception 'Use a PNG favicon'; end if;
  raw:=decode(substr(target,23),'base64');
  if length(raw)<32 or encode(substring(raw from 1 for 8),'hex')<>'89504e470d0a1a0a' or encode(substring(raw from 13 for 12),'hex')<>'494844520000004000000040' then raise exception 'Use a 64 by 64 PNG favicon'; end if;
 end if;
 update public.site_favicon set png=target,previous_png=old.png,revision=revision+1,updated_at=clock_timestamp() where id;
 return public.admin_favicon();
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_site_icon(p_slot text, p_source_slot text DEFAULT NULL::text, p_path_d text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not private.is_admin((select auth.uid())) then raise exception 'Not an MFA-verified administrator' using errcode='42501'; end if;
 if not exists(select 1 from public.site_icon_slots where slot=p_slot) then raise exception 'Unknown icon slot' using errcode='22023'; end if;
 if p_source_slot is not null and not exists(select 1 from public.site_icon_slots where slot=p_source_slot) then raise exception 'Unknown source icon' using errcode='22023'; end if;
 if p_source_slot is not null and p_path_d is not null then raise exception 'Choose one icon source' using errcode='22023'; end if;
 if p_path_d is not null and (length(p_path_d) not between 3 and 1200 or p_path_d !~ '^[MmLlHhVvCcSsQqTtAaZz0-9 .,+-]+$') then raise exception 'Invalid SVG path' using errcode='22023'; end if;
 if p_source_slot is null and p_path_d is null then
  delete from public.site_icon_overrides where slot=p_slot;
 else
  insert into public.site_icon_overrides(slot,source_slot,path_d) values(p_slot,p_source_slot,p_path_d)
  on conflict(slot) do update set source_slot=excluded.source_slot,path_d=excluded.path_d,updated_at=now();
 end if;
 insert into public.site_icon_revisions(slot,source_slot,path_d,actor_id) values(p_slot,p_source_slot,p_path_d,(select auth.uid()));
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_user_status(p_user_id uuid, p_status text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_admin((select auth.uid())) then raise exception 'admin required'; end if;
  if p_user_id=(select auth.uid()) then raise exception 'cannot moderate your own account'; end if;
  if p_status not in ('active','suspended') or length(trim(coalesce(p_reason,'')))<3 then raise exception 'valid status and reason required'; end if;
  update public.profiles set account_status=p_status where id=p_user_id;
  if not found then raise exception 'user not found'; end if;
  insert into public.admin_moderation_log(admin_id,action,target_type,target_id,reason) values ((select auth.uid()),'user_'||p_status,'user',p_user_id,left(trim(p_reason),500));
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_vacancy_status(p_vacancy_id uuid, p_status text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_admin((select auth.uid())) then raise exception 'admin required'; end if;
  if p_status not in ('active','paused','removed') or length(trim(coalesce(p_reason,'')))<3 then raise exception 'valid status and reason required'; end if;
  update public.vacancies set status=p_status where id=p_vacancy_id;
  if not found then raise exception 'vacancy not found'; end if;
  insert into public.admin_moderation_log(admin_id,action,target_type,target_id,reason) values ((select auth.uid()),'vacancy_'||p_status,'vacancy',p_vacancy_id,left(trim(p_reason),500));
end $function$

CREATE OR REPLACE FUNCTION public.record_lister_journey(p_events jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare item jsonb; accepted integer := 0; event_name text;
begin
  if jsonb_typeof(p_events) <> 'array' or jsonb_array_length(p_events) > 20 then
    raise exception 'Invalid journey batch' using errcode='22023';
  end if;
  for item in select value from jsonb_array_elements(p_events) as value loop
    event_name := item->>'event_name';
    if event_name not in (
      'lister_session_started','lister_landing_viewed','list_property_clicked','signup_started','signup_completed','signup_pending_confirmation',
      'listing_started','property_type_completed','location_started','location_completed','listing_details_started','listing_details_completed',
      'photos_completed','pricing_completed','listing_previewed','publish_clicked','listing_record_created','listing_submitted',
      'step_ready','photo_upload','journey_error'
    ) then raise exception 'Unsupported journey event' using errcode='22023'; end if;
    begin
    insert into public.analytics_events(
      event_id,user_id,event_name,vacancy_id,route,visitor_id,session_id,journey_id,
      source,medium,campaign,campaign_id,adset_id,ad_id,content_id,first_source,first_medium,first_campaign,
      referrer_host,landing_path,step,device_class,browser_family,os_family,duration_ms,active_ms,error_code
    ) values (
      (item->>'event_id')::uuid,(select auth.uid()),event_name,nullif(item->>'vacancy_id','')::uuid,left(item->>'route',120),
      (item->>'visitor_id')::uuid,(item->>'session_id')::uuid,nullif(item->>'journey_id','')::uuid,
      left(item->>'source',80),left(item->>'medium',80),left(item->>'campaign',100),left(item->>'campaign_id',100),
      left(item->>'adset_id',100),left(item->>'ad_id',100),left(item->>'content_id',100),
      left(item->>'first_source',80),left(item->>'first_medium',80),left(item->>'first_campaign',100),
      left(item->>'referrer_host',120),left(item->>'landing_path',120),left(item->>'step',40),
      left(item->>'device_class',16),left(item->>'browser_family',24),left(item->>'os_family',24),
      least(greatest(coalesce((item->>'duration_ms')::integer,0),0),3600000),
      least(greatest(coalesce((item->>'active_ms')::integer,0),0),3600000),left(item->>'error_code',60)
    );
    accepted := accepted + 1;
    exception when unique_violation then null;
    end;
  end loop;
  return accepted;
end $function$

CREATE OR REPLACE FUNCTION public.record_lister_journey_v2(p_events jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare item jsonb; accepted integer:=0; event text;
begin
 if p_events is null or jsonb_typeof(p_events)<>'array' or jsonb_array_length(p_events)>20 or octet_length(p_events::text)>32768 then
  raise exception 'Invalid journey batch' using errcode='22023'; end if;
 for item in select value from jsonb_array_elements(p_events) loop
  event:=item->>'event_name';
  if event is null or event not in ('lister_session_started','lister_landing_viewed','list_property_clicked','listing_started','step_ready','publish_clicked','listing_record_created','listing_submitted','photo_upload','journey_error')
   or item->>'event_id' is null or item->>'visitor_id' is null or item->>'session_id' is null
   or coalesce(item->>'journey_mode','new') not in ('new','legacy')
   or coalesce((item->>'to_step')::integer,0) not between 0 and 3
   or coalesce((item->>'from_step')::integer,0) not between 0 and 3
   or coalesce(item->>'route','other') not in ('find','listing','list','create','auth','other') then
   raise exception 'Unsupported journey fields' using errcode='22023'; end if;
  begin
   insert into public.analytics_events(event_id,user_id,event_name,route,visitor_id,session_id,journey_id,source,medium,campaign,
    campaign_id,adset_id,ad_id,content_id,referrer_host,device_class,duration_ms,error_code,
    journey_version,previous_event_id,occurred_at,from_step,to_step,unit_request_id,journey_mode)
   values((item->>'event_id')::uuid,auth.uid(),event,item->>'route',(item->>'visitor_id')::uuid,(item->>'session_id')::uuid,
    nullif(item->>'journey_id','')::uuid,left(item->>'source',80),left(item->>'medium',80),left(item->>'campaign',100),
    left(item->>'campaign_id',100),left(item->>'adset_id',100),left(item->>'ad_id',100),left(item->>'content_id',100),
    left(item->>'referrer_host',120),left(item->>'device_class',16),least(greatest(coalesce((item->>'duration_ms')::integer,0),0),3600000),left(item->>'error_code',60),
    2,nullif(item->>'previous_event_id','')::uuid,
    greatest(now()-interval '24 hours',least(now(),coalesce((item->>'occurred_at')::timestamptz,now()))),
    (item->>'from_step')::smallint,(item->>'to_step')::smallint,nullif(item->>'unit_request_id','')::uuid,coalesce(item->>'journey_mode','new'));
   accepted:=accepted+1;
  exception when unique_violation then null;
  end;
 end loop;
 return accepted;
end $function$
